"""Generates the side-scroller fixture's art (README.md): the cave's two
parallax walls as one tileset with its map, and the props. Pixel art, one
texel two screen pixels at 960x540. Deterministic; rerun it to change them:

    python3 tests/fixtures/side-scroller/art.py
"""

import math
import os
import random

from PIL import Image

HERE = os.path.dirname(os.path.abspath(__file__))
ASSETS = os.path.join(HERE, "assets")
TILE = 32
WALL_W, WALL_H = 512, 160  # each parallax wall, in texels


def rgb(h):
    return tuple(int(h[i : i + 2], 16) for i in (1, 3, 5))


def noise1(seed, n, octaves):
    """Smooth 1D value noise, 0..1, n samples (wraps, so the walls repeat)."""
    rnd = random.Random(seed)
    out = [0.0] * n
    amp, total = 1.0, 0.0
    for period in octaves:
        pts = [rnd.random() for _ in range(n // period)]
        for i in range(n):
            f = i / period
            a, b = pts[int(f) % len(pts)], pts[(int(f) + 1) % len(pts)]
            t = f - int(f)
            t = t * t * (3 - 2 * t)
            out[i] += amp * (a + (b - a) * t)
        total += amp
        amp *= 0.5
    return [v / total for v in out]


def wall(seed, base, rim, dark, top_depth, bottom_depth, columns, holes):
    """A cave wall: stalactites hanging from the top, stalagmites from the
    bottom, rock columns joining them; moonlit rims on the upward faces."""
    img = Image.new("RGBA", (WALL_W, WALL_H), (0, 0, 0, 0))
    px = img.load()
    rnd = random.Random(seed)
    top = noise1(seed, WALL_W, [64, 16, 4])
    bot = noise1(seed + 1, WALL_W, [64, 16, 4])
    spikes = [0.0] * WALL_W
    for _ in range(WALL_W // 18):
        c, w, d = rnd.randrange(WALL_W), rnd.randint(3, 9), rnd.randint(10, top_depth)
        for dx in range(-w, w + 1):
            x = (c + dx) % WALL_W
            spikes[x] = max(spikes[x], d * (1 - abs(dx) / (w + 1)) ** 1.6)
    solid = [[False] * WALL_W for _ in range(WALL_H)]
    for x in range(WALL_W):
        t = int(8 + top[x] * top_depth * 0.6 + spikes[x])
        b = int(WALL_H - 6 - bot[x] * bottom_depth)
        for y in range(WALL_H):
            solid[y][x] = y < t or y >= b
    for cx, w in columns:
        prof = noise1(seed + cx, WALL_H, [32, 8])
        for y in range(WALL_H):
            # A column pinched at its middle, wider where it meets rock.
            pinch = 0.55 + 0.45 * abs(y / WALL_H - 0.5) * 2
            half = int(w * pinch * (0.8 + 0.4 * prof[y]))
            for dx in range(-half, half + 1):
                solid[y][(cx + dx) % WALL_W] = True
    for hx, hy, hr in holes:
        for y in range(WALL_H):
            for x in range(WALL_W):
                if (x - hx) ** 2 + ((y - hy) * 1.4) ** 2 < hr * hr:
                    solid[y][x] = False
    shade = noise1(seed + 7, WALL_W * 4, [24, 6])
    for y in range(WALL_H):
        for x in range(WALL_W):
            if not solid[y][x]:
                continue
            up = y > 0 and not solid[y - 1][x]
            up2 = y > 1 and not solid[y - 2][x]
            left = not solid[y][(x - 1) % WALL_W]
            # Bands of rock strata, ordered dither between base and dark.
            band = shade[(x + y * 3) % len(shade)]
            c = dark if band < 0.42 and (x + y) % 2 == 0 else base
            if up:
                c = rim
            elif up2 or left:
                c = tuple((a + b) // 2 for a, b in zip(rim, base))
            px[x, y] = c + (255,)
    return img


def save(img, *path):
    p = os.path.join(ASSETS, *path)
    os.makedirs(os.path.dirname(p), exist_ok=True)
    img.save(p, optimize=True)


def walls():
    far = wall(3, rgb("#1c2440"), rgb("#3b4f7a"), rgb("#161c33"), 46, 40,
               [(90, 10), (300, 14), (430, 8)], [(200, 20, 26), (370, 140, 20)])
    mid = wall(11, rgb("#121726"), rgb("#2b3756"), rgb("#0d111c"), 60, 52,
               [(40, 22), (250, 28), (400, 18)], [])
    sheet = Image.new("RGBA", (WALL_W, WALL_H * 2), (0, 0, 0, 0))
    sheet.paste(far, (0, 0))
    sheet.paste(mid, (0, WALL_H))
    save(sheet, "bg", "walls.png")
    # Pixel art: lossless, no mips, sampled nearest (not the ETC1S default).
    with open(os.path.join(ASSETS, "bg", "walls.png.ogt"), "w") as f:
        f.write("type import\nversion 1\n---\ntexture {\n  kind pixel\n}\n")
    cols, rows = WALL_W // TILE, WALL_H * 2 // TILE
    with open(os.path.join(ASSETS, "bg", "walls.ogt"), "w") as f:
        f.write("type tileset\nversion 1\n---\n# Generated by art.py: the far wall above the near one.\n")
        f.write(f'texture "bg/walls.png"\ngrid {TILE} {TILE} {cols} {rows}\nfilter nearest\n')
    half = rows // 2
    lines = ["type tilemap", "version 1", "---",
             "# Generated by art.py: the two walls behind the cave, each",
             "# repeating along x at its own parallax; the far one stays unlit.",
             f"size {cols} {half}", f"tile {TILE} {TILE}", "unit 2", 'tileset "bg/walls.ogt"']
    for name, first, z, par, lit in (("far", 0, -30, "0.3 0.6", "false"), ("near", half * cols, -20, "0.6 0.8", "true")):
        lines += [f"layer {name} {{", f"  z {z}", f"  parallax {par}", "  repeat x", f"  lit {lit}"]
        for r in range(half):
            lines.append("  row " + " ".join(str(first + r * cols + c) for c in range(cols)))
        lines.append("}")
    with open(os.path.join(ASSETS, "bg", "cave.ogt"), "w") as f:
        f.write("\n".join(lines) + "\n")


def draw(w, h, fn):
    img = Image.new("RGBA", (w, h), (0, 0, 0, 0))
    px = img.load()
    for y in range(h):
        for x in range(w):
            c = fn(x, y)
            if c is not None:
                px[x, y] = (rgb(c) if isinstance(c, str) else c) + (255,)
    return img


def pillar():
    """A broken stone column: a capital, fluting, a cracked top."""
    w, h = 22, 84
    rnd = random.Random(5)
    crack = [rnd.randint(0, 6) for _ in range(w)]

    def f(x, y):
        if y < 4 + crack[x]:
            return None
        if y >= h - 6 or (8 + crack[x] <= y < 14 and True):
            # Base and capital: wider slabs.
            return "#55607a" if y in (h - 6, 8 + crack[x]) else ("#3a4258" if x % 7 else "#2c3245")
        if x < 2 or x >= w - 2:
            return None
        flute = (x - 2) % 5
        if flute == 0:
            return "#262b3b"
        if flute == 1:
            return "#4d5872"
        return "#3a4258" if (y // 9 + x) % 6 else "#333a4f"
    return draw(w, h, f)


def torch():
    """An iron sconce holding a wooden torch."""
    def f(x, y):
        if 3 <= x <= 5 and 4 <= y < 16:
            return "#6b4426" if x != 5 else "#4a2e19"
        if y in (8, 9) and 1 <= x <= 7:
            return "#3b3d45"
        if 16 <= y < 20 and 2 <= x <= 6:
            return "#2a2c33"
        if 2 <= y < 5 and 2 <= x <= 6:
            return "#1f1208"
        return None
    return draw(9, 20, f)


def flame():
    """A flame, white at its root to deep orange at its tips (drawn additive)."""
    w, h = 9, 14

    def f(x, y):
        cx = 4 + math.sin(y * 0.9) * 0.6
        r = (y / h) ** 0.8 * 4.2
        d = abs(x - cx)
        if d > r:
            return None
        t = d / max(r, 0.01) * 0.6 + (1 - y / h) * 0.6
        if t < 0.35:
            return "#fff4c8"
        if t < 0.6:
            return "#ffc24a"
        if t < 0.85:
            return "#ff7a1c"
        return "#c2390e"
    return draw(w, h, f)


def tufts(seed):
    """Moss and grass along the floor's top edge."""
    rnd = random.Random(seed)
    w, h = 24, 7
    blades = [(rnd.randrange(w), rnd.randint(2, h)) for _ in range(14)]

    def f(x, y):
        for bx, bh in blades:
            if x == bx and y >= h - bh:
                return "#3f7a6e" if y < h - bh + 2 else "#24514c"
        if y == h - 1 and rnd.random() < 0.9:
            return "#1d3d3b"
        return None
    return draw(w, h, f)


def mushroom():
    """Glowing cave mushrooms, cyan caps on pale stalks."""
    caps = [(3, 6, 3), (9, 3, 4), (14, 7, 2)]

    def f(x, y):
        for cx, cy, r in caps:
            if cy <= y < cy + 2 and abs(x - cx) <= r:
                return "#9ff4ff" if y == cy and abs(x - cx) < r else "#45c6dd"
            if x == cx and cy + 2 <= y < 12:
                return "#c9d6d8"
        return None
    return draw(17, 12, f)


def sword():
    """A sword left standing in the floor, Hollow Knight's grave marker."""
    def f(x, y):
        if x == 3 and 0 <= y < 3:
            return "#8a6a3a"
        if y == 3 and 0 <= x <= 6:
            return "#6d717d"
        if 2 <= x <= 4 and 4 <= y < 26:
            return "#c4c9d4" if x == 2 else ("#8d93a1" if x == 3 else "#5d6270")
        return None
    return draw(7, 26, f)


def chain():
    def f(x, y):
        k = y % 6
        if (k < 3 and x in (0, 2) and k > 0) or (k in (0, 3) and x == 1) or (k >= 3 and x == 1):
            return "#4b4e58" if k != 4 else "#6c707c"
        return None
    return draw(3, 60, f)


def moon():
    """The moon seen through the hole in the cave roof."""
    r = 13

    def f(x, y):
        d = math.hypot(x - r, y - r)
        if d > r:
            return None
        crater = math.hypot(x - 8, y - 9) < 3 or math.hypot(x - 17, y - 16) < 2
        return "#c7d4ef" if crater else ("#eef3ff" if d < r - 1.5 else "#a9b9df")
    return draw(2 * r + 1, 2 * r + 1, f)


def main():
    walls()
    props = (("pillar", pillar()), ("torch", torch()), ("flame", flame()),
             ("tufts_a", tufts(1)), ("tufts_b", tufts(2)), ("mushroom", mushroom()),
             ("sword", sword()), ("chain", chain()), ("moon", moon()))
    sheet = ["type flipbook", "version 1", "---",
             "# Generated by art.py: the loose prop PNGs, one still clip each,",
             "# packed by the cook in cells of their own size.",
             "align feet", "crop each", "padding 1", "filter nearest"]
    sizes = []
    for name, img in props:
        save(img, "props", name + ".png")
        sheet.append(f'source "{name}.png"')
        x0, y0, x1, y1 = img.getbbox()
        # The cell: the drawn bounds and the padding all round.
        sizes.append(f"  {name}: {{ w: {x1 - x0 + 2}, h: {y1 - y0 + 2} }},")
    with open(os.path.join(ASSETS, "props", "props.ogt"), "w") as f:
        f.write("\n".join(sheet) + "\n")
    with open(os.path.join(HERE, "src", "art.ts"), "w") as f:
        f.write("// Generated by art.py: each prop's cell in props/props.ogt, in texels.\n")
        f.write("export const PROPS = {\n" + "\n".join(sizes) + "\n} as const;\n")


if __name__ == "__main__":
    main()
